//#region src/three/post.js
function makeComposer({ renderer, scene, camera, width, height, quality = "high" }) {
	const target = new WebGLRenderTarget(width, height, {
		type: HalfFloatType,
		colorSpace: "",
		samples: 0
	});
	const composer = new EffectComposer(renderer, target);
	composer.setSize(width, height);
	const render = new RenderPass(scene, camera);
	composer.addPass(render);
	let ao = null;
	try {
		ao = new GTAOPass(scene, camera, Math.round(width / 2), Math.round(height / 2));
		ao.output = GTAOPass.OUTPUT.Default;
		ao.blendIntensity = quality === "high" ? .45 : .3;
		ao.updateGtaoMaterial?.({
			radius: .012,
			distanceExponent: 1,
			thickness: .05,
			scale: 1,
			samples: quality === "high" ? 16 : 8
		});
		const half = (w, h) => GTAOPass.prototype.setSize.call(ao, Math.max(2, Math.round(w / 2)), Math.max(2, Math.round(h / 2)));
		ao.setSize = half;
		composer.addPass(ao);
	} catch (err) {
		ao = null;
		console.warn("AO 패스를 건너뛴다", err?.message || err);
	}
	const bloom = new UnrealBloomPass(new Vector2(width, height), .42, .72, .86);
	bloom.enabled = quality === "high";
	composer.addPass(bloom);
	const output = new OutputPass();
	composer.addPass(output);
	let smaa = null;
	try {
		smaa = new SMAAPass(width, height);
		composer.addPass(smaa);
	} catch (err) {
		smaa = null;
		console.warn("SMAA 패스를 건너뛴다", err?.message || err);
	}
	return {
		composer,
		passes: {
			render,
			ao,
			bloom,
			output,
			smaa
		},
		target
	};
}
