	if (t === "경로당") return "senior";
	if (t === "의료기관" || t === "약국") return "medical";
	if (t === "행정복지센터") return "admin";
	if (t === "체육시설") return "sports";
	if (t === "경찰" || t === "소방") return "safety";
	if (t === "복지시설") return "care";
