		this.quality = want;
		const p = PRESET[want];
		if (this.passes) {
			if (this.passes.bloom) this.passes.bloom.enabled = p.bloom;
			if (this.passes.ao) this.passes.ao.enabled = p.ao && !!this.aoWanted && this.viewMode === "3d";
			if (this.passes.smaa) this.passes.smaa.enabled = p.smaa;
		}
